"""Recorre recursivamente todos los hijos del contenedor (self)
y recolecta los custom.item en un JSON único."""

def gather_items(component):
	items = []

	# Si este componente tiene custom.item, lo guardamos
	if hasattr(component.custom, "item"):
		item = component.custom.item
		items.append({
			"papoItemID": item.get("papoItemID"),
			"registerTypeID": item.get("registerTypeID"),
			"answer": item.get("answer")
		})

	# Recorremos hijos recursivamente
	for child in component.getChildren():
		items.extend(gather_items(child))

	return items
